sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from eval_lab.runner import discover_tasks

REFS = {'two_sum': 'def two_sum(nums, target):\n    seen = {}\n    for j, x in enumerate(nums):\n        if target - x in seen:\n            return (seen[target - x], j)\n        seen[x] = j\n', 'is_palindrome': 'def is_palindrome(s):\n    f = [c.lower() for c in s if c.isalnum()]\n    return f == f[::-1]\n', 'fizzbuzz_sum': 'def fizzbuzz_sum(n):\n    s = lambda k, d: d * (k // d) * (k // d + 1) // 2\n    return s(n, 3) + s(n, 5) - s(n, 15)\n', 'reverse_words': 'def reverse_words(s):\n    return " ".join(s.split()[::-1])\n', 'max_subarray': 'def max_subarray(nums):\n    best = cur = nums[0]\n    for x in nums[1:]:\n        cur = max(x, cur + x)\n        best = max(best, cur)\n    return best\n', 'binary_search': 'def binary_search(nums, target):\n    lo, hi = 0, len(nums) - 1\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[mid] < target:\n            lo = mid + 1\n        else:\n            hi = mid - 1\n    return -1\n', 'merge_intervals': 'def merge_intervals(intervals):\n    out = []\n    for s, e in sorted(intervals):\n        if out and s <= out[-1][1]:\n            out[-1][1] = max(out[-1][1], e)\n        else:\n            out.append([s, e])\n    return out\n', 'valid_parentheses': 'def valid_parentheses(s):\n    pairs = {")": "(", "]": "[", "}": "{"}\n    stack = []\n    for ch in s:\n        if ch in "([{":\n            stack.append(ch)\n        elif not stack or stack.pop() != pairs[ch]:\n            return False\n    return not stack\n', 'climb_stairs': 'def climb_stairs(n):\n    a, b = 1, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a\n', 'product_except_self': 'def product_except_self(nums):\n    n = len(nums)\n    out = [1] * n\n    left = 1\n    for i in range(n):\n        out[i] = left\n        left *= nums[i]\n    right = 1\n    for i in range(n - 1, -1, -1):\n        out[i] *= right\n        right *= nums[i]\n    return out\n', 'rotate_array': 'def rotate_array(nums, k):\n    if not nums:\n        return []\n    k %= len(nums)\n    return nums[-k:] + nums[:-k] if k else list(nums)\n', 'first_unique_char': 'def first_unique_char(s):\n    from collections import Counter\n    counts = Counter(s)\n    for i, ch in enumerate(s):\n        if counts[ch] == 1:\n            return i\n    return -1\n', 'group_anagrams': 'def group_anagrams(strs):\n    from collections import defaultdict\n    groups = defaultdict(list)\n    for w in strs:\n        groups["".join(sorted(w))].append(w)\n    return list(groups.values())\n', 'top_k_frequent': 'def top_k_frequent(nums, k):\n    from collections import Counter\n    return [x for x, _ in Counter(nums).most_common(k)]\n', 'longest_unique_substring': 'def length_of_longest_substring(s):\n    last = {}\n    start = best = 0\n    for i, ch in enumerate(s):\n        if ch in last and last[ch] >= start:\n            start = last[ch] + 1\n        last[ch] = i\n        best = max(best, i - start + 1)\n    return best\n', 'contains_nearby_duplicate': 'def contains_nearby_duplicate(nums, k):\n    seen = {}\n    for i, x in enumerate(nums):\n        if x in seen and i - seen[x] <= k:\n            return True\n        seen[x] = i\n    return False\n', 'missing_number': 'def missing_number(nums):\n    n = len(nums)\n    return n * (n + 1) // 2 - sum(nums)\n', 'single_number': 'def single_number(nums):\n    from functools import reduce\n    from operator import xor\n    return reduce(xor, nums)\n', 'count_bits': 'def count_bits(n):\n    out = [0] * (n + 1)\n    for i in range(1, n + 1):\n        out[i] = out[i >> 1] + (i & 1)\n    return out\n', 'hamming_distance': 'def hamming_distance(x, y):\n    return bin(x ^ y).count("1")\n', 'min_stack': 'class MinStack:\n    def __init__(self):\n        self.stack = []\n        self.mins = []\n\n    def push(self, val):\n        self.stack.append(val)\n        self.mins.append(min(val, self.mins[-1]) if self.mins else val)\n\n    def pop(self):\n        self.stack.pop()\n        self.mins.pop()\n\n    def top(self):\n        return self.stack[-1]\n\n    def get_min(self):\n        return self.mins[-1]\n', 'lru_cache': 'from collections import OrderedDict\n\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.cap = capacity\n        self.data = OrderedDict()\n\n    def get(self, key):\n        if key not in self.data:\n            return -1\n        self.data.move_to_end(key)\n        return self.data[key]\n\n    def put(self, key, value):\n        self.data[key] = value\n        self.data.move_to_end(key)\n        if len(self.data) > self.cap:\n            self.data.popitem(last=False)\n', 'roman_to_int': 'def roman_to_int(s):\n    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}\n    total = 0\n    for i, ch in enumerate(s):\n        if i + 1 < len(s) and vals[ch] < vals[s[i + 1]]:\n            total -= vals[ch]\n        else:\n            total += vals[ch]\n    return total\n', 'int_to_roman': 'def int_to_roman(num):\n    table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]\n    out = []\n    for value, sym in table:\n        while num >= value:\n            out.append(sym)\n            num -= value\n    return "".join(out)\n', 'my_atoi': 'def my_atoi(s):\n    s = s.lstrip()\n    if not s:\n        return 0\n    sign = 1\n    if s[0] in "+-":\n        sign = -1 if s[0] == "-" else 1\n        s = s[1:]\n    digits = []\n    for ch in s:\n        if not ch.isdigit():\n            break\n        digits.append(ch)\n    if not digits:\n        return 0\n    val = sign * int("".join(digits))\n    return max(-(2**31), min(2**31 - 1, val))\n', 'spiral_order': 'def spiral_order(matrix):\n    out = []\n    while matrix:\n        out += matrix.pop(0)\n        if matrix and matrix[0]:\n            for row in matrix:\n                out.append(row.pop())\n        if matrix:\n            out += matrix.pop()[::-1]\n        if matrix and matrix[0]:\n            for row in matrix[::-1]:\n                out.append(row.pop(0))\n    return out\n', 'word_break': 'def word_break(s, word_dict):\n    words = set(word_dict)\n    dp = [True] + [False] * len(s)\n    for i in range(1, len(s) + 1):\n        dp[i] = any(dp[j] and s[j:i] in words for j in range(i))\n    return dp[len(s)]\n', 'coin_change': 'def coin_change(coins, amount):\n    INF = amount + 1\n    dp = [0] + [INF] * amount\n    for a in range(1, amount + 1):\n        dp[a] = min((dp[a - c] + 1 for c in coins if c <= a), default=INF)\n    return dp[amount] if dp[amount] <= amount else -1\n', 'unique_paths': 'def unique_paths(m, n):\n    from math import comb\n    return comb(m + n - 2, m - 1)\n', 'house_robber': 'def house_robber(nums):\n    take = skip = 0\n    for x in nums:\n        take, skip = skip + x, max(skip, take)\n    return max(take, skip)\n', 'can_finish': 'def can_finish(num_courses, prerequisites):\n    from collections import defaultdict, deque\n    graph = defaultdict(list)\n    indeg = [0] * num_courses\n    for a, b in prerequisites:\n        graph[b].append(a)\n        indeg[a] += 1\n    queue = deque(i for i in range(num_courses) if indeg[i] == 0)\n    done = 0\n    while queue:\n        node = queue.popleft()\n        done += 1\n        for nxt in graph[node]:\n            indeg[nxt] -= 1\n            if indeg[nxt] == 0:\n                queue.append(nxt)\n    return done == num_courses\n', 'dijkstra': 'def dijkstra(n, edges, src):\n    import heapq\n    from collections import defaultdict\n    graph = defaultdict(list)\n    for u, v, w in edges:\n        graph[u].append((v, w))\n    dist = [float("inf")] * n\n    dist[src] = 0\n    heap = [(0, src)]\n    while heap:\n        d, u = heapq.heappop(heap)\n        if d > dist[u]:\n            continue\n        for v, w in graph[u]:\n            nd = d + w\n            if nd < dist[v]:\n                dist[v] = nd\n                heapq.heappush(heap, (nd, v))\n    return dist\n', 'kth_largest': 'def kth_largest(nums, k):\n    import heapq\n    return heapq.nlargest(k, nums)[-1]\n'}


def main():
    tasks = discover_tasks("tasks")
    missing = [t.task_id for t in tasks if t.task_id not in REFS]
    if missing:
        sys.exit(f"No reference solution for: {missing}")
    failed = []
    for t in tasks:
        with tempfile.TemporaryDirectory() as tmp:
            Path(tmp, "solution.py").write_text(REFS[t.task_id])
            r = subprocess.run(
                [sys.executable, "-m", "pytest", "-q", str(t.tests_dir.resolve()),
                 "--rootdir", tmp, "-p", "no:cacheprovider", "--import-mode=importlib"],
                cwd=tmp, capture_output=True, text=True)
            print(("OK  " if r.returncode == 0 else "FAIL"), t.task_id)
            if r.returncode != 0:
                failed.append((t.task_id, r.stdout[-800:]))
    for tid, out in failed:
        print(f"--- {tid} ---")
        print(out)
    print(f"{len(tasks) - len(failed)}/{len(tasks)} tasks validated")
    sys.exit(1 if failed else 0)


if __name__ == "__main__":
    main()
